  }

  .thread-card .avatar {
    width: 36px;
    height: 36px;
  }

  .thread-time {
    display: none;
  }

  .thread-body {
    grid-column: 1 / -1;
    padding: 6px 2px 14px;
    font-size: 14px;
  }

  .attachments {
    grid-column: 1 / -1;
  }

  .reply-row {
    margin-left: 0;
  }

  .compose-window {
    inset: 0;
    width: 100%;
    height: 100dvh;
    border-radius: 0;
    transform: translateY(30px);
  }

  .compose-window.compose-maximized {
    inset: 0;
    width: 100%;
    height: 100dvh;
    border-radius: 0;
    translate: none;
    transform: none;
  }

  .compose-window.minimized {
    top: auto;
    height: 48px;
  }

  .compose-header {
    min-height: 48px;
  }

  .contact-suggestions {
    left: 12px !important;
    width: calc(100vw - 24px);
  }

  .toast-region {
    bottom: 76px;
  }
}

@media (max-width: 420px) {
  .category-tab {
    flex-basis: 100px;
    min-width: 100px;
  }

  .category-count {
    display: none;
  }

  .mail-subject {
    max-width: 64%;
  }

  .reply-button {
    flex: 1;
    padding: 0 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
